import { GoogleGenAI, Type } from "@google/genai";
import { Gig } from '../types';

// Ensure API key is present; in a real app, handle this more gracefully
const apiKey = process.env.API_KEY || '';
const ai = new GoogleGenAI({ apiKey });

export const generateProposal = async (gig: Gig, coderNote: string): Promise<string> => {
  if (!apiKey) {
    return "Error: API Key not configured in environment.";
  }

  const prompt = `
    Act as a "Vibe Coder" - a modern, AI-savvy developer who builds things fast using tools like Cursor, v0, and Replit.

    You are applying for the following gig:
    Title: ${gig.title}
    Client Vibe: ${gig.clientVibe}
    Recommended Stack: ${gig.recommendedStack}

    The user (Vibe Coder) has added this personal note: "${coderNote}"

    Write a short, punchy, and professional proposal (max 150 words) to the client. 
    Explain how you will use the AI stack to deliver this ridiculously fast. 
    Adopt a confident, "I got this" tone.
    Focus on speed and aesthetic.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        thinkingConfig: { thinkingBudget: 0 }, // Disable thinking for faster speed on simple creative writing
      }
    });

    return response.text || "Failed to generate proposal.";
  } catch (error) {
    console.error("Gemini API Error:", error);
    return "Error generating proposal. Please check your API key and try again.";
  }
};

