import React, { useState } from 'react';
import { Gig } from '../types';
import { generateProposal } from '../services/geminiService';
import { SparklesIcon, XIcon, LoaderIcon, CodeIcon } from './Icons';

interface ProposalGeneratorProps {
  gig: Gig;
  onClose: () => void;
}

const ProposalGenerator: React.FC<ProposalGeneratorProps> = ({ gig, onClose }) => {
  const [coderNote, setCoderNote] = useState('');
  const [proposal, setProposal] = useState('');
  const [loading, setLoading] = useState(false);

  const handleGenerate = async () => {
    setLoading(true);
    const result = await generateProposal(gig, coderNote);
    setProposal(result);
    setLoading(false);
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-950/80 backdrop-blur-sm">
      <div className="bg-slate-900 border border-slate-700 rounded-2xl shadow-2xl max-w-2xl w-full max-h-[90vh] overflow-y-auto flex flex-col">

        {/* Header */}
        <div className="flex justify-between items-center p-6 border-b border-slate-800 bg-slate-900 sticky top-0 z-10">
          <div>
            <h2 className="text-xl font-bold text-white flex items-center gap-2">
              <SparklesIcon className="text-vibe-400" />
              Vibe Proposal Generator
            </h2>
            <p className="text-slate-400 text-sm">Gig: {gig.title}</p>
          </div>
          <button onClick={onClose} className="text-slate-400 hover:text-white transition-colors">
            <XIcon />
          </button>
        </div>

        <div className="p-6 space-y-6">

          {/* Gig Details Summary */}
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
             <div className="bg-slate-800/50 p-4 rounded-xl border border-slate-700">
                <h4 className="text-xs text-slate-500 uppercase font-bold mb-2">The Vibe</h4>
                <p className="text-slate-300 text-sm italic">"{gig.clientVibe}"</p>
             </div>
             <div className="bg-slate-800/50 p-4 rounded-xl border border-slate-700">
                <h4 className="text-xs text-slate-500 uppercase font-bold mb-2">The Stack</h4>
                <p className="text-slate-300 text-sm font-mono">{gig.recommendedStack}</p>
             </div>
          </div>

          {/* Vibe Code Approach Steps */}
          <div>
            <h3 className="text-white font-semibold mb-3 flex items-center gap-2">
                <CodeIcon className="w-4 h-4 text-vibe-400" />
                Vibe Code Approach
            </h3>
            <div className="space-y-3">
                {gig.approach.map((step) => (
                    <div key={step.stepNumber} className="flex gap-4 p-3 rounded-lg bg-slate-800/30 border border-slate-700/50">
                        <span className="flex-shrink-0 w-6 h-6 rounded-full bg-vibe-900/50 text-vibe-400 border border-vibe-500/30 flex items-center justify-center text-xs font-mono">
                            {step.stepNumber}
                        </span>
                        <p className="text-sm text-slate-300">
                           <span className="font-semibold text-slate-400">Step {step.stepNumber}:</span> {step.instruction}
                        </p>
                    </div>
                ))}
            </div>
          </div>

          <hr className="border-slate-800" />

          {/* User Input */}
          <div>
            <label className="block text-sm font-medium text-slate-300 mb-2">
              Add your personal flair (optional):
            </label>
            <textarea
              className="w-full bg-slate-950 border border-slate-700 rounded-xl p-3 text-slate-200 focus:ring-2 focus:ring-vibe-500 focus:border-transparent outline-none transition-all resize-none text-sm"
              rows={3}
              placeholder="e.g. I specialize in dark mode UI and using Redis for speed..."
              value={coderNote}
              onChange={(e) => setCoderNote(e.target.value)}
            />
          </div>

          {/* Action Button */}
          {!proposal && (
            <button
              onClick={handleGenerate}
              disabled={loading}
              className={`w-full py-3 px-4 rounded-xl font-bold text-white flex items-center justify-center gap-2 transition-all ${
                loading 
                  ? 'bg-slate-700 cursor-not-allowed' 
                  : 'bg-gradient-to-r from-vibe-600 to-vibe-500 hover:from-vibe-500 hover:to-vibe-400 shadow-lg shadow-vibe-500/20'
              }`}
            >
              {loading ? (
                <>
                  <LoaderIcon className="animate-spin" />
                  Generating Vibes...
                </>
              ) : (
                <>
                  <SparklesIcon />
                  Generate Proposal with Gemini
                </>
              )}
            </button>
          )}

          {/* Output */}
          {proposal && (
            <div className="animate-in fade-in slide-in-from-bottom-4 duration-500">
              <div className="flex justify-between items-center mb-2">
                 <h3 className="text-white font-semibold">Your Generated Proposal</h3>
                 <button 
                   onClick={() => {navigator.clipboard.writeText(proposal)}}
                   className="text-xs text-vibe-400 hover:text-vibe-300 underline"
                 >
                   Copy to Clipboard
                 </button>
              </div>
              <div className="bg-slate-950 border border-vibe-900/50 rounded-xl p-4 relative overflow-hidden group">
                <div className="absolute inset-0 bg-gradient-to-br from-vibe-500/5 to-transparent pointer-events-none" />
                <p className="text-slate-300 text-sm whitespace-pre-wrap font-mono leading-relaxed relative z-10">
                  {proposal}
                </p>
              </div>

              <div className="mt-4 flex gap-3">
                 <button onClick={onClose} className="flex-1 py-2 rounded-lg border border-slate-700 text-slate-300 hover:bg-slate-800 transition-colors text-sm">
                    Close
                 </button>
                 <button onClick={handleGenerate} className="flex-1 py-2 rounded-lg bg-slate-800 text-white hover:bg-slate-700 transition-colors text-sm">
                    Regenerate
                 </button>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default ProposalGenerator;

import React, { useState, useMemo } from 'react';
import { gigs } from './data';
import { Gig, GigCategory } from './types';
import GigCard from './components/GigCard';
import ProposalGenerator from './components/ProposalGenerator';
import { SearchIcon, SparklesIcon, CodeIcon, BotIcon, ZapIcon, BarChartIcon, GamepadIcon } from './components/Icons';

const App = () => {
  const [selectedCategory, setSelectedCategory] = useState<GigCategory | 'All'>('All');
  const [searchQuery, setSearchQuery] = useState('');
  const [selectedGig, setSelectedGig] = useState<Gig | null>(null);

  const filteredGigs = useMemo(() => {
    return gigs.filter((gig) => {
      const matchesCategory = selectedCategory === 'All' || gig.category === selectedCategory;
      const matchesSearch = gig.title.toLowerCase().includes(searchQuery.toLowerCase()) || 
                            gig.clientVibe.toLowerCase().includes(searchQuery.toLowerCase());
      return matchesCategory && matchesSearch;
    });
  }, [selectedCategory, searchQuery]);

  const categories = [
    { label: 'All', icon: SparklesIcon, value: 'All' },
    { label: 'Web Apps', icon: CodeIcon, value: GigCategory.WEB_APP },
    { label: 'Extensions', icon: ZapIcon, value: GigCategory.CHROME_EXTENSION },
    { label: 'Data Viz', icon: BarChartIcon, value: GigCategory.DATA_VIZ },
    { label: 'Automation', icon: BotIcon, value: GigCategory.AUTOMATION },
    { label: 'Games', icon: GamepadIcon, value: GigCategory.GAME },
  ];

  return (
    <div className="min-h-screen bg-[#0f172a] bg-[radial-gradient(ellipse_at_top,_var(--tw-gradient-stops))] from-slate-900 via-[#0f172a] to-black text-slate-100 font-sans selection:bg-vibe-500/30">

      {/* Navbar */}
      <nav className="sticky top-0 z-40 w-full glass-panel border-b border-white/5">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex items-center justify-between h-16">
            <div className="flex items-center gap-2">
              <div className="w-8 h-8 rounded-lg bg-gradient-to-tr from-vibe-500 to-vibe-300 flex items-center justify-center shadow-[0_0_15px_rgba(20,184,166,0.5)]">
                <SparklesIcon className="text-white w-5 h-5" />
              </div>
              <span className="text-xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-white to-slate-400">
                Vibe Coding Gigs
              </span>
            </div>
            <div className="hidden md:block">
              <span className="text-xs font-mono text-slate-500 border border-slate-800 bg-slate-900/50 px-3 py-1 rounded-full">
                {gigs.length} Active Gigs
              </span>
            </div>
          </div>
        </div>
      </nav>

      {/* Hero Section */}
      <div className="relative pt-16 pb-12 overflow-hidden">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 relative z-10 text-center">
            <h1 className="text-4xl md:text-6xl font-extrabold tracking-tight text-white mb-6">
              Build fast. <span className="text-transparent bg-clip-text bg-gradient-to-r from-vibe-400 to-neon-blue neon-text">Code with Vibe.</span>
            </h1>
            <p className="max-w-2xl mx-auto text-lg text-slate-400 mb-8">
              The marketplace for "Vibe Coders" using AI tools like Cursor, Replit Agent, and v0 to ship prototypes and micro-apps in record time.
            </p>

            {/* Search Bar */}
            <div className="max-w-xl mx-auto relative group">
              <div className="absolute inset-0 bg-gradient-to-r from-vibe-500 to-purple-600 rounded-xl blur opacity-25 group-hover:opacity-40 transition duration-1000"></div>
              <div className="relative bg-slate-900 border border-slate-700 rounded-xl flex items-center p-2 shadow-2xl">
                <SearchIcon className="ml-3 text-slate-500 w-5 h-5" />
                <input 
                  type="text" 
                  placeholder="Search gigs by keyword or vibe..." 
                  className="w-full bg-transparent border-none focus:ring-0 text-slate-200 placeholder-slate-500 px-4 py-2"
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                />
              </div>
            </div>
        </div>

        {/* Background Decorative Grid */}
        <div className="absolute top-0 left-0 w-full h-full overflow-hidden -z-10 opacity-20 pointer-events-none">
            <div className="absolute inset-0 bg-[linear-gradient(to_right,#80808012_1px,transparent_1px),linear-gradient(to_bottom,#80808012_1px,transparent_1px)] bg-[size:24px_24px]"></div>
        </div>
      </div>

      {/* Main Content */}
      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 pb-20">

        {/* Category Filters */}
        <div className="flex flex-wrap justify-center gap-2 mb-10">
          {categories.map((cat) => (
            <button
              key={cat.label}
              onClick={() => setSelectedCategory(cat.value as any)}
              className={`flex items-center gap-2 px-4 py-2 rounded-full text-sm font-medium transition-all duration-300 border ${
                selectedCategory === cat.value
                  ? 'bg-vibe-900/50 border-vibe-500 text-vibe-300 shadow-[0_0_10px_rgba(20,184,166,0.2)]'
                  : 'bg-slate-800/50 border-slate-700 text-slate-400 hover:bg-slate-800 hover:text-white'
              }`}
            >
              <cat.icon className="w-4 h-4" />
              {cat.label}
            </button>
          ))}
        </div>

        {/* Gigs Grid */}
        {filteredGigs.length > 0 ? (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {filteredGigs.map((gig) => (
              <GigCard key={gig.id} gig={gig} onSelect={setSelectedGig} />
            ))}
          </div>
        ) : (
          <div className="text-center py-20">
            <div className="inline-flex items-center justify-center w-16 h-16 rounded-full bg-slate-800 mb-4">
               <SearchIcon className="w-8 h-8 text-slate-500" />
            </div>
            <h3 className="text-xl font-medium text-slate-300">No gigs found</h3>
            <p className="text-slate-500 mt-2">Try adjusting your filters or search terms.</p>
          </div>
        )}
      </main>

      {/* Footer */}
      <footer className="border-t border-slate-800 py-12 bg-slate-950">
        <div className="max-w-7xl mx-auto px-4 text-center">
            <p className="text-slate-500 text-sm">
                &copy; {new Date().getFullYear()} Vibe Coding Gigs. Built for the AI era.
            </p>
        </div>
      </footer>

      {/* Proposal Modal */}
      {selectedGig && (
        <ProposalGenerator gig={selectedGig} onClose={() => setSelectedGig(null)} />
      )}
    </div>
  );
};

