      <button 
        className="w-full mt-2 py-2 px-4 rounded-lg bg-slate-700 text-slate-200 text-sm font-semibold hover:bg-vibe-600 hover:text-white transition-all flex items-center justify-center gap-2"
      >
        <span>Accept Challenge</span>
        <SparklesIcon className="w-3 h-3" />
      </button>
