export type ProblemType = 'Headache' | 'Migraine';
export type PainLevel = 'Low' | 'Medium' | 'High' | 'Critical';
export type Repeatability = 'Constant' | 'Daily' | 'Weekly' | 'Monthly' | 'Once';

