export const generateProjectPlan = async (gig: Gig): Promise<ProjectPlan> => {
  if (!apiKey) throw new Error("API Key missing");

  const prompt = `
    You are a Senior Technical Product Manager breaking down a "Vibe Coding" project.

    Project: ${gig.title}
    Stack: ${gig.recommendedStack}
    Vibe: ${gig.clientVibe}

    1. List 3-5 specific software tools/services the user needs to sign up for or install (e.g. VS Code, Cursor, Replit, Supabase, OpenAI API). Provide the real main URL.
    2. Break the project into 5-8 granular, actionable development tasks. Each task should be clear enough for an intermediate developer to execute.

    Return strict JSON.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        responseMimeType: 'application/json',
        responseSchema: planSchema,
      }
    });

    if (response.text) {
      return JSON.parse(cleanJson(response.text)) as ProjectPlan;
    }
    throw new Error("Empty response");
  } catch (error) {
    console.error("Gemini API Error generating plan:", error);
    // Return empty plan but don't throw, allowing UI to handle partial state
    return { tools: [], tasks: [] };
  }
};

export const createGigChat = (gig: Gig): Chat => {
  if (!apiKey) throw new Error("API Key missing");

  return ai.chats.create({
    model: 'gemini-3-flash-preview',
    config: {
      systemInstruction: `You are a friendly, expert "Vibe Coding" Mentor. 
      You are guiding a user to build the project: "${gig.title}".
      The recommended stack is: ${gig.recommendedStack}.
      Your goal is to unblock them, provide code snippets when asked, and explain concepts simply.
      Keep answers concise and actionable.`
    }
  });
};

import React, { useState, useEffect, useRef } from 'react';
import { Gig, ProjectPlan, ChatMessage } from '../types';
import { generateProjectPlan, createGigChat } from '../services/geminiService';
import { XIcon, LoaderIcon, CodeIcon, BotIcon, ZapIcon, SparklesIcon, PuzzleIcon } from './Icons';
import { GenerateContentResponse, Chat } from "@google/genai";

interface GigGuideProps {
  gig: Gig;
  onClose: () => void;
}

type Tab = 'setup' | 'plan' | 'assistant';

const GigGuide: React.FC<GigGuideProps> = ({ gig, onClose }) => {
  const [activeTab, setActiveTab] = useState<Tab>('setup');
  const [plan, setPlan] = useState<ProjectPlan | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(false);
  const [chatHistory, setChatHistory] = useState<ChatMessage[]>([]);
  const [chatInput, setChatInput] = useState('');
  const [isSending, setIsSending] = useState(false);

  // Ref for the Chat instance
  const chatSession = useRef<Chat | null>(null);
  const messagesEndRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    let mounted = true;

    const init = async () => {
      try {
        setLoading(true);
        setError(false);
        // 1. Generate the plan
        const generatedPlan = await generateProjectPlan(gig);

        // 2. Initialize Chat
        chatSession.current = createGigChat(gig);

        if (mounted) {
          if (generatedPlan.tools.length === 0 && generatedPlan.tasks.length === 0) {
              setError(true);
              // If plan fails, default to Assistant tab so user isn't stuck
              setActiveTab('assistant');
          } else {
              setPlan(generatedPlan);
          }

          // Add initial greeting
          setChatHistory([{
            role: 'model',
            text: `Hi! I'm your Vibe Mentor. I've analyzed "${gig.title}". Check out the Setup tab to get your tools ready, or ask me anything here!`
          }]);
        }
      } catch (err) {
        console.error(err);
        if (mounted) {
            setError(true);
            setActiveTab('assistant');
        }
      } finally {
        if (mounted) setLoading(false);
      }
    };

    init();
    return () => { mounted = false; };
  }, [gig]);

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [chatHistory, activeTab]);

  const handleSendMessage = async () => {
    if (!chatInput.trim() || !chatSession.current) return;

    const userMsg = chatInput;
    setChatInput('');
    setChatHistory(prev => [...prev, { role: 'user', text: userMsg }]);
    setIsSending(true);

    try {
      const response = await chatSession.current.sendMessage({ message: userMsg });
      const text = (response as GenerateContentResponse).text || "I'm thinking...";

      setChatHistory(prev => [...prev, { role: 'model', text: text }]);
    } catch (error) {
      setChatHistory(prev => [...prev, { role: 'model', text: "Sorry, I had trouble connecting. Try again?" }]);
    } finally {
      setIsSending(false);
    }
  };

  if (loading) {
    return (
      <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-950/80 backdrop-blur-sm">
        <div className="bg-slate-900 border border-slate-700 rounded-2xl shadow-2xl p-8 flex flex-col items-center max-w-sm w-full">
          <LoaderIcon className="w-12 h-12 text-vibe-400 animate-spin mb-4" />
          <h3 className="text-xl font-bold text-white">Initializing Mission</h3>
          <p className="text-slate-400 text-center mt-2">Generating battle plan and summoning AI mentor...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-950/90 backdrop-blur-md">
      <div className="bg-slate-900 border border-slate-700 rounded-2xl shadow-2xl max-w-4xl w-full h-[85vh] flex flex-col overflow-hidden">

        {/* Header */}
        <div className="flex justify-between items-center p-4 border-b border-slate-800 bg-slate-950">
          <div className="flex items-center gap-3">
             <div className="bg-vibe-500/10 p-2 rounded-lg">
                <CodeIcon className="text-vibe-400 w-6 h-6" />
             </div>
             <div>
                <h2 className="text-lg font-bold text-white">Mission Control</h2>
                <p className="text-slate-400 text-xs">{gig.title}</p>
             </div>
          </div>
          <button onClick={onClose} className="text-slate-500 hover:text-white transition-colors p-2 hover:bg-slate-800 rounded-lg">
            <XIcon className="w-6 h-6" />
          </button>
        </div>

        {/* Tabs */}
        <div className="flex border-b border-slate-800 bg-slate-900">
          <button 
            onClick={() => setActiveTab('setup')}
            className={`flex-1 py-4 text-sm font-medium flex items-center justify-center gap-2 border-b-2 transition-all ${activeTab === 'setup' ? 'border-vibe-500 text-vibe-400 bg-slate-800/50' : 'border-transparent text-slate-400 hover:text-white hover:bg-slate-800'}`}
          >
            <ZapIcon className="w-4 h-4" /> Setup
          </button>
          <button 
            onClick={() => setActiveTab('plan')}
            className={`flex-1 py-4 text-sm font-medium flex items-center justify-center gap-2 border-b-2 transition-all ${activeTab === 'plan' ? 'border-vibe-500 text-vibe-400 bg-slate-800/50' : 'border-transparent text-slate-400 hover:text-white hover:bg-slate-800'}`}
          >
            <PuzzleIcon className="w-4 h-4" /> Tasks
          </button>
          <button 
            onClick={() => setActiveTab('assistant')}
            className={`flex-1 py-4 text-sm font-medium flex items-center justify-center gap-2 border-b-2 transition-all ${activeTab === 'assistant' ? 'border-vibe-500 text-vibe-400 bg-slate-800/50' : 'border-transparent text-slate-400 hover:text-white hover:bg-slate-800'}`}
          >
            <BotIcon className="w-4 h-4" /> Assistant
          </button>
        </div>

        {/* Content Area */}
        <div className="flex-grow overflow-y-auto bg-[#0B1120] relative">

            {/* SETUP TAB */}
            {activeTab === 'setup' && (
                plan ? (
               <div className="p-8 max-w-3xl mx-auto space-y-8 animate-in fade-in slide-in-from-bottom-2 duration-300">
                  <div className="bg-indigo-900/20 border border-indigo-500/30 rounded-xl p-6">
                     <h3 className="text-indigo-300 font-bold text-lg mb-2">Recommended Stack</h3>
                     <p className="text-indigo-100/80">{gig.recommendedStack}</p>
                  </div>

                  <div>
                     <h3 className="text-white font-bold text-xl mb-4">Install & Account Checklist</h3>
                     <div className="grid gap-4">
                        {plan.tools.map((tool, idx) => (
                           <div key={idx} className="bg-slate-800/50 border border-slate-700 rounded-xl p-5 hover:border-vibe-500/30 transition-colors flex items-start justify-between group">
                              <div>
                                 <h4 className="text-white font-semibold text-lg">{tool.name}</h4>
                                 <p className="text-slate-400 text-sm mt-1 mb-3">{tool.reason}</p>
                                 <a 
                                    href={tool.url} 
                                    target="_blank" 
                                    rel="noreferrer" 
                                    className="inline-flex items-center gap-1 text-xs font-bold text-vibe-400 hover:text-vibe-300 bg-vibe-950/50 px-3 py-1.5 rounded border border-vibe-900"
                                 >
                                    Get Tool <ZapIcon className="w-3 h-3" />
                                 </a>
                              </div>
                              <div className="bg-slate-900 text-slate-500 font-mono text-xs px-2 py-1 rounded">
                                 Required
                              </div>
                           </div>
                        ))}
                     </div>
                  </div>

                  <div className="flex justify-end">
                      <button onClick={() => setActiveTab('plan')} className="bg-vibe-600 hover:bg-vibe-500 text-white px-6 py-3 rounded-xl font-bold transition-all shadow-lg shadow-vibe-900/20">
                          Next: View Tasks &rarr;
                      </button>
                  </div>
               </div>
               ) : (
                <div className="p-12 text-center">
                    <div className="inline-flex items-center justify-center w-16 h-16 rounded-full bg-slate-800 mb-4 text-rose-500">
                        <XIcon className="w-8 h-8" />
                    </div>
                    <h3 className="text-lg font-bold text-white">Plan Generation Failed</h3>
                    <p className="text-slate-400 mt-2 max-w-md mx-auto">
                        We couldn't automatically generate the tools checklist. Use the <strong>Assistant</strong> tab to ask for manual guidance.
                    </p>
                    <button 
                        onClick={() => setActiveTab('assistant')}
                        className="mt-6 px-6 py-2 bg-vibe-600 text-white rounded-lg hover:bg-vibe-500 font-bold"
                    >
                        Ask Assistant
                    </button>
                </div>
               )
            )}

            {/* TASKS TAB */}
            {activeTab === 'plan' && (
                plan ? (
                <div className="p-8 max-w-3xl mx-auto animate-in fade-in slide-in-from-bottom-2 duration-300">
                    <h3 className="text-white font-bold text-xl mb-6 flex items-center gap-2">
                        <SparklesIcon className="text-yellow-400" /> 
                        Your Vibe Code Plan
                    </h3>
                    <div className="space-y-4">
                        {plan.tasks.map((task, idx) => (
                            <label key={task.id} className="flex gap-4 items-start p-5 rounded-xl bg-slate-800/40 border border-slate-700 hover:bg-slate-800 cursor-pointer transition-all group select-none">
                                <div className="relative flex items-center justify-center mt-1">
