                                    {msg.role === 'model' && (
                                       <div className="flex items-center gap-2 mb-2 text-xs font-bold text-vibe-400 uppercase tracking-wider">
                                          <BotIcon className="w-3 h-3" /> Mentor
                                       </div>
                                    )}
                                    <p className="whitespace-pre-wrap text-sm leading-relaxed">{msg.text}</p>
                                </div>
                            </div>
                        ))}
                        <div ref={messagesEndRef} />
                        {isSending && (
                           <div className="flex justify-start">
                              <div className="bg-slate-800 rounded-2xl p-4 rounded-tl-none border border-slate-700 flex gap-1 items-center">
                                 <div className="w-2 h-2 bg-slate-500 rounded-full animate-bounce" style={{ animationDelay: '0ms' }}></div>
                                 <div className="w-2 h-2 bg-slate-500 rounded-full animate-bounce" style={{ animationDelay: '150ms' }}></div>
                                 <div className="w-2 h-2 bg-slate-500 rounded-full animate-bounce" style={{ animationDelay: '300ms' }}></div>
                              </div>
                           </div>
                        )}
                    </div>

                    <div className="p-4 bg-slate-900 border-t border-slate-800">
                        <div className="relative">
                            <input 
                                type="text"
                                className="w-full bg-slate-950 border border-slate-700 rounded-xl pl-4 pr-12 py-4 text-slate-200 focus:outline-none focus:border-vibe-500 focus:ring-1 focus:ring-vibe-500 transition-all placeholder-slate-600"
                                placeholder="Ask for code snippets, help with errors, or next steps..."
                                value={chatInput}
                                onChange={(e) => setChatInput(e.target.value)}
                                onKeyDown={(e) => e.key === 'Enter' && !isSending && handleSendMessage()}
                                disabled={isSending}
                            />
                            <button 
                                onClick={handleSendMessage}
                                disabled={!chatInput.trim() || isSending}
                                className="absolute right-2 top-2 bottom-2 bg-slate-800 hover:bg-vibe-600 text-white p-2 rounded-lg transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
                            >
                                <SparklesIcon className="w-5 h-5" />
                            </button>
                        </div>
                    </div>
                </div>
            )}
        </div>
      </div>
    </div>
  );
};

